import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, vec3, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Vector3,
  } = THREE;

  const root = new Group();
  root.name = 'collection-title';

  const resources = [];
  const timelines = [];
  const primitiveResults = [];

  const gradientMaterial = new MeshBasicNodeMaterial();
  gradientMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.055, 0.055, 0.067),
      smoothGradient(uv().y)
    ),
    smoothGradient(uv().y)
  );

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    gradientMaterial
  );
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdrop.geometry, backdrop.material);

  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.96,
  });

  const surface = new Mesh(
    new PlaneGeometry(6.15, 3.85),
    surfaceMaterial
  );
  surface.name = 'collection-image-surface';
  surface.position.set(0, -0.25, -1.35);
  root.add(surface);
  resources.push(surface.geometry, surface.material);

  const imageMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2',
    transparent: true,
    opacity: 0.88,
  });

  const imagePlane = new Mesh(
    new PlaneGeometry(5.55, 3.15),
    imageMaterial
  );
  imagePlane.name = 'collection-feature-image';
  imagePlane.position.set(0, -0.18, -1.12);
  root.add(imagePlane);
  resources.push(imagePlane.geometry, imagePlane.material);

  const frameMaterial = new MeshBasicNodeMaterial({
    color: '#16161d',
  });

  const topFrame = new Mesh(new BoxGeometry(6.18, 0.035, 0.035), frameMaterial);
  topFrame.position.set(0, 1.68, -1.02);
  root.add(topFrame);
  resources.push(topFrame.geometry, topFrame.material);

  const bottomFrame = new Mesh(new BoxGeometry(6.18, 0.035, 0.035), frameMaterial);
  bottomFrame.position.set(0, -2.18, -1.02);
  root.add(bottomFrame);
  resources.push(bottomFrame.geometry);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
  });

  const accentRule = new Mesh(
    new BoxGeometry(1.2, 0.045, 0.045),
    accentMaterial
  );
  accentRule.name = 'signal-red-accent';
  accentRule.position.set(-2.45, 1.38, -0.9);
  root.add(accentRule);
  resources.push(accentRule.geometry, accentRule.material);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.name = 'collection-text';

  let textY = 0.85;
  for (const item of items) {
    const content = typeof item?.text === 'string' ? item.text : '';
    if (!content) continue;

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item.typography?.fontSize ?? 96,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: item.role === 'label' ? 8 : 0,
    });

    textObject.position.set(0, textY, -0.72);
    textGroup.add(textObject);
    textY -= item.role === 'headline' ? 0.62 : 0.28;
  }

  root.add(textGroup);

  const loadingTasks = [];
  if (config.imageUrl) {
    loadingTasks.push(
      ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
        imageMaterial.map = texture;
        imageMaterial.needsUpdate = true;
      }).catch(() => {})
    );
  }

  const settle = gsap.timeline();
  settle.fromTo(
    textGroup.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.42, ease: 'power3.out' }
  );
  settle.to(
    textGroup.scale,
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );
  timelines.push(settle);

  for (const primitive of config.cinematicPrimitives ?? []) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler !== 'function') continue;

    const result = handler(root, primitive.params);
    if (result) primitiveResults.push(result);
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const result of primitiveResults) {
      result?.cleanup?.();
      result?.timeline?.kill?.();
    }

    for (const timeline of timelines) timeline.kill();

    root.traverse((object) => {
      if (object.geometry) object.geometry.dispose?.();
      if (object.material) {
        if (Array.isArray(object.material)) {
          object.material.forEach((material) => material.dispose?.());
        } else {
          object.material.dispose?.();
        }
      }
    });
  };

  void loadingTasks;
  return root;
}

function smoothGradient(value) {
  return value.smoothstep(0.0, 1.0);
}
